package verification

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

// chainlinker_modernization_02k — the Go SDK verifies the SHARED cross-language fixture
// (sdk/testdata/merkle_golden.json), generated by the server's internal/merkle. Every
// server-generated proof must fold to the server-generated root here — byte-identity proof.

type goldenInclusion struct {
	Index    int      `json:"index"`
	TreeSize int      `json:"tree_size"`
	LeafHash string   `json:"leaf_hash"`
	Path     []string `json:"path"`
}
type goldenConsistency struct {
	M          int      `json:"m"`
	N          int      `json:"n"`
	FirstRoot  string   `json:"first_root"`
	SecondRoot string   `json:"second_root"`
	Proof      []string `json:"proof"`
}
type goldenFixture struct {
	Root        string              `json:"root"`
	Inclusion   []goldenInclusion   `json:"inclusion"`
	Consistency []goldenConsistency `json:"consistency"`
}

func loadMerkleGolden(t *testing.T) goldenFixture {
	t.Helper()
	_, thisFile, _, _ := runtime.Caller(0)
	path := filepath.Join(filepath.Dir(thisFile), "testdata", "shared", "merkle_golden.json") // a copy of sdk/testdata/merkle_golden.json; publish-sdks.sh refuses one that differs
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read golden: %v", err)
	}
	var g goldenFixture
	if err := json.Unmarshal(raw, &g); err != nil {
		t.Fatalf("unmarshal golden: %v", err)
	}
	return g
}

func mustHexList(t *testing.T, hs []string) [][]byte {
	t.Helper()
	out := make([][]byte, len(hs))
	for i, h := range hs {
		b, err := hex.DecodeString(h)
		if err != nil {
			t.Fatalf("hex %q: %v", h, err)
		}
		out[i] = b
	}
	return out
}

func TestMerkleGolden_CrossLanguage(t *testing.T) {
	g := loadMerkleGolden(t)
	root, err := hex.DecodeString(g.Root)
	if err != nil {
		t.Fatalf("root hex: %v", err)
	}
	for _, inc := range g.Inclusion {
		lh, _ := hex.DecodeString(inc.LeafHash)
		if !VerifyMerkleInclusion(lh, inc.Index, inc.TreeSize, mustHexList(t, inc.Path), root) {
			t.Errorf("golden inclusion idx=%d failed in Go SDK", inc.Index)
		}
		// Negative: tamper the leaf.
		if VerifyMerkleInclusion(MerkleLeafHash([]byte("tampered")), inc.Index, inc.TreeSize, mustHexList(t, inc.Path), root) {
			t.Errorf("golden inclusion idx=%d: tampered leaf verified", inc.Index)
		}
	}
	for _, c := range g.Consistency {
		ra, _ := hex.DecodeString(c.FirstRoot)
		rb, _ := hex.DecodeString(c.SecondRoot)
		if !VerifyMerkleConsistency(c.M, c.N, ra, rb, mustHexList(t, c.Proof)) {
			t.Errorf("golden consistency m=%d n=%d failed in Go SDK", c.M, c.N)
		}
	}
}
